//! Synthetic current-versus-historical calculation contracts. No real data or external calls.
use nxt_os::{store::Store,firm::staff::{Identity,Role},tax::{Tax,calculations as c,models::*,reports::ReportRequest,family_workflow::MembersInput,batch::{Create,Operation,Selection,Step,ItemState},filing_desk::{self,FilerGrant,DeskConfirmation}}};
use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn digest(v:&impl serde::Serialize)->String {hex::encode(Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn who()->Identity{Identity{user_id:"synthetic-filer".into(),display_name:"Synthetic filer".into(),role:Role::Admin,clients:vec!["A".into()],break_glass:false,mfa:true,must_change_password:false}}
fn input(name:&str)->ReturnInput{serde_json::from_value(json!({"program":"T1","tax_year":2025,"jurisdiction":"AB","name":name,"client_ref":"A","inputs":{"scope_confirmed":true,"full_year_resident":true,"employment_income_cents":5000000}})).unwrap()}
async fn calculated(t:&Tax,key:Option<&str>)->TaxReturn{let r=t.save(None,input("Synthetic current record")).await.unwrap_or_else(|e|panic!("save: {}",e.1));t.calculate(&r.id,RevisionInput{expected_revision:r.revision,idempotency_key:key.map(str::to_owned)}).await.unwrap_or_else(|e|panic!("calculate: {}",e.1))}
fn make_historical(r:&mut TaxReturn,rules:Option<&str>){let s=r.calculation.as_mut().unwrap();if let Some(rules)=rules{s.result["ruleset"]=json!(rules);}else{s.result.as_object_mut().unwrap().remove("ruleset");}s.output_hash=digest(&s.result);r.calculations=vec![s.clone()];}
async fn seed(store:&Store,r:&TaxReturn){let mut s:TaxState=store.get_json("tax:state:v1").await.unwrap().unwrap();*s.returns.iter_mut().find(|x|x.id==r.id).unwrap()=r.clone();store.set_json("tax:state:v1",&s).await.unwrap();}
fn req(historical:bool)->ReportRequest{serde_json::from_value(json!({"client_ref":"A","columns":["line:15000","line:42000","total:income_tax"],"include_historical_results":historical})).unwrap()}

#[test]fn verified_2025_top_up_credit_cases_use_the_current_worksheet(){
 for jurisdiction in ["AB","ON","BC"] {
  for (tuition,donation,top_up) in [(3_977_500,0,0),(3_977_501,0,0),(3_957_500,20_000,0),(4_000_000,0,113)] {
   let result=c::calculate("T1",2025,jurisdiction,&json!({"scope_confirmed":true,"full_year_resident":true,"provincial_adjustments_not_applicable":true,"employment_income_cents":5_000_000,"tuition_cents":tuition,"donations_cents":donation,"credits_verified":true})).unwrap();
   assert!(result.supported,"{jurisdiction}: {:?}",result.diagnostics);
   assert!(!result.diagnostics.iter().any(|d|d.code=="top_up_tax_credit_not_implemented"));
   assert_eq!(result.lines.iter().find(|l|l.code=="34990").unwrap().amount,top_up);
  }
 }
}
#[tokio::test]async fn top_up_credit_review_requires_verification_and_current_calculation(){
 let store=Store::memory();let t=Tax::new(store.clone());let mut i=input("Synthetic large credit");i.inputs["tuition_cents"]=json!(4_000_000);i.inputs["credits_verified"]=json!(false);let r=t.save(None,i).await.ok().unwrap();let r=t.calculate(&r.id,RevisionInput{expected_revision:r.revision,idempotency_key:None}).await.ok().unwrap();
 let before=store.get("tax:state:v1").await.unwrap();assert_eq!(t.transition(&r.id,TransitionInput{expected_revision:r.revision,status:"in_review".into(),note:"Synthetic only".into(),reviewer:"Synthetic preparer".into(),filing_reference:String::new(),t183_envelope_id:String::new()}).await.err().unwrap().0.as_u16(),409);assert_eq!(store.get("tax:state:v1").await.unwrap(),before);
 let report=t.report(req(false),Some(&who())).await.ok().unwrap();assert_eq!(report["rows"][0]["calculation_state"],"current_blocked");assert!(report["rows"][0]["total:income_tax"].is_null());
 let mut edit=ReturnInput::from(&r);edit.expected_revision=Some(r.revision);edit.inputs["credits_verified"]=json!(true);let edited=t.save(Some(&r.id),edit).await.ok().unwrap();assert!(edited.calculation.is_none());let current=t.calculate(&r.id,RevisionInput{expected_revision:edited.revision,idempotency_key:None}).await.ok().unwrap();assert_eq!(current.calculation.as_ref().unwrap().result["supported"],true);
 let reviewed=t.transition(&r.id,TransitionInput{expected_revision:current.revision,status:"in_review".into(),note:"Synthetic only".into(),reviewer:"Synthetic preparer".into(),filing_reference:String::new(),t183_envelope_id:String::new()}).await.ok().unwrap();assert_eq!(reviewed.status,"in_review");
 let report=t.report(req(false),Some(&who())).await.ok().unwrap();assert_ne!(report["rows"][0]["calculation_state"],"current_blocked");assert!(!report["rows"][0]["total:income_tax"].is_null());
}

#[test]fn official_2025_medical_and_donation_output_lines_match_their_contracts(){
 for j in ["AB","ON","BC"]{let r=c::calculate("T1",2025,j,&json!({"scope_confirmed":true,"full_year_resident":true,"provincial_adjustments_not_applicable":true,"employment_income_cents":5000000,"medical_expenses_cents":400000,"donations_cents":120000,"tuition_cents":300000,"credits_verified":true})).unwrap();let line=|code|r.lines.iter().find(|l|l.code==code).unwrap().amount;assert!(r.supported,"{j}: {:?}",r.diagnostics);assert_eq!(r.ruleset,c::RULESET);assert_eq!(line("33099"),400000);assert_eq!(line("33200"),250000);assert_eq!(line("34900"),31900);assert_eq!(line("donation_credit"),31900);assert_eq!(line("extra_federal_credits"),111650);}
}
#[test]fn every_nonzero_business_or_cpp_claim_is_held_even_when_verified(){
 for j in ["AB","ON","BC"]{for key in ["self_employment_gross_cents","self_employment_expenses_cents","self_employment_cca_cents","se_cpp_deduction_cents","se_cpp_credit_cents"]{let mut v=json!({"scope_confirmed":true,"full_year_resident":true,"provincial_adjustments_not_applicable":true,"employment_income_cents":5000000,"t2125_verified":true,"se_cpp_verified":true});v[key]=json!(1);match c::calculate("T1",2025,j,&v){Ok(r)=>{assert!(!r.supported);assert!(r.diagnostics.iter().any(|d|d.code=="self_employed_cpp_payable_not_implemented"&&d.blocks_review));if key.starts_with("se_cpp_"){assert!(r.diagnostics.iter().any(|d|d.code=="orphan_self_employed_cpp"&&d.blocks_review));}},Err(e)=>assert!(key=="self_employment_cca_cents"&&e.contains("loss"),"unexpected failure for {j}/{key}: {e}")}}}
 // The old $5,000 trigger must not accidentally leave a lower positive business result supported.
 for gross in [300000,400000,500000]{let r=c::calculate("T1",2025,"AB",&json!({"scope_confirmed":true,"full_year_resident":true,"t2125_verified":true,"se_cpp_verified":true,"self_employment_gross_cents":gross})).unwrap();assert!(!r.supported);assert!(r.diagnostics.iter().any(|d|d.code=="self_employed_cpp_payable_not_implemented"));}
}
#[test]fn absent_and_explicit_zero_claims_do_not_add_cpp_holds_or_change_annual_math(){
 let base=json!({"scope_confirmed":true,"full_year_resident":true,"employment_income_cents":5000000});let absent=c::calculate("T1",2025,"AB",&base).unwrap();let mut zero=base.clone();for key in ["self_employment_gross_cents","self_employment_expenses_cents","self_employment_cca_cents","se_cpp_deduction_cents","se_cpp_credit_cents"]{zero[key]=json!(0);}let explicit=c::calculate("T1",2025,"AB",&zero).unwrap();assert_eq!(serde_json::to_vec(&absent).unwrap(),serde_json::to_vec(&explicit).unwrap());assert_ne!(digest(&base),digest(&zero));assert!(absent.supported);
 let y26=c::calculate("T1",2026,"AB",&json!({"scope_confirmed":true,"full_year_resident":true,"credits_verified":true,"interest_income_cents":5000000,"medical_expenses_cents":400000,"donations_cents":120000})).unwrap();assert_eq!(y26.lines.iter().find(|l|l.code=="33099").unwrap().amount,250000);assert_eq!(y26.lines.iter().find(|l|l.code=="donation_credit").unwrap().amount,31800);assert!(!y26.diagnostics.iter().any(|d|d.code=="self_employed_cpp_payable_not_implemented"));
}
#[tokio::test]async fn earlier_or_missing_ruleset_blocks_all_review_transitions_without_mutation(){
 for rules in [Some("nxt-ca-2025.1"),None]{let store=Store::memory();let t=Tax::new(store.clone());let mut r=calculated(&t,None).await;make_historical(&mut r,rules);
 for (status,target) in [("calculated","in_review"),("in_review","approved"),("approved","filed"),("in_review","in_review"),("approved","approved"),("filed","filed")]{r.status=status.into();seed(&store,&r).await;let before=store.get("tax:state:v1").await.unwrap();let denied=t.transition(&r.id,TransitionInput{expected_revision:r.revision,status:target.into(),note:"Synthetic review".into(),reviewer:"Synthetic reviewer".into(),filing_reference:String::new(),t183_envelope_id:String::new()}).await.err().unwrap();assert_eq!(denied.0.as_u16(),409);assert!(denied.1.contains("ruleset"));assert_eq!(store.get("tax:state:v1").await.unwrap(),before);}
 r.status="approved".into();assert!(nxt_os::tax::t183::draft(&r).unwrap_err().contains("ruleset"));assert!(filing_desk::blockers(&r).iter().any(|v|v["code"]=="stale_calculation"));}
}
#[tokio::test]async fn current_and_old_results_are_classified_without_rewriting_saved_snapshots(){
 let store=Store::memory();let t=Tax::new(store.clone());let a=who();let mut old=calculated(&t,None).await;let current=calculated(&t,None).await;make_historical(&mut old,Some("nxt-ca-2025.2"));seed(&store,&old).await;
 let family=t.save_family_members_for(None,MembersInput{label:"Synthetic comparison".into(),primary_return_id:old.id.clone(),spouse_return_id:current.id.clone(),expected_primary_revision:old.revision,expected_spouse_revision:current.revision,expected_client_ref:"A".into(),expected_family_sha256:None},&a).await.unwrap_or_else(|e|panic!("family: {}",e.1));assert_eq!(family["primary_current_supported_calculation"],false);assert_eq!(family["spouse_current_supported_calculation"],true);
 let before=store.get("tax:state:v1").await.unwrap();let report=t.report(req(false),Some(&a)).await.unwrap_or_else(|e|panic!("report: {}",e.1));let row=report["rows"].as_array().unwrap().iter().find(|v|v["id"]==old.id).unwrap();assert_eq!(row["calculation_state"],"stale");assert!(row["line:15000"].is_null());let history=t.report(req(true),Some(&a)).await.unwrap_or_else(|e|panic!("history report: {}",e.1));assert_eq!(history["rows"].as_array().unwrap().iter().find(|v|v["id"]==old.id).unwrap()["line:15000"],5000000);
 let package=t.package(&old.id).await.unwrap_or_else(|e|panic!("package: {}",e.1));assert_eq!(package["current_ruleset"],c::RULESET);assert_eq!(package["current_calculation_ruleset_current"],false);assert_eq!(package["calculation_snapshot"],serde_json::to_value(&old.calculation).unwrap());assert_eq!(store.get("tax:state:v1").await.unwrap(),before);
}
#[tokio::test]async fn old_idempotency_receipt_is_historical_but_new_explicit_calculate_uses_current_rules(){
 let store=Store::memory();let t=Tax::new(store.clone());let mut old=calculated(&t,Some("synthetic-old-key")).await;make_historical(&mut old,Some("nxt-ca-2025.2"));seed(&store,&old).await;let old_snapshot=serde_json::to_vec(old.calculation.as_ref().unwrap()).unwrap();let before=store.get("tax:state:v1").await.unwrap();
 let replay=t.calculate(&old.id,RevisionInput{expected_revision:1,idempotency_key:Some("synthetic-old-key".into())}).await.unwrap_or_else(|e|panic!("receipt replay: {}",e.1));assert_eq!(serde_json::to_vec(&replay).unwrap(),serde_json::to_vec(&old).unwrap());assert_eq!(store.get("tax:state:v1").await.unwrap(),before);
 let next=t.calculate(&old.id,RevisionInput{expected_revision:old.revision,idempotency_key:Some("synthetic-new-key".into())}).await.unwrap_or_else(|e|panic!("new calculation: {}",e.1));assert_eq!(next.calculation.as_ref().unwrap().result["ruleset"],c::RULESET);assert_eq!(next.calculations.len(),2);assert_eq!(serde_json::to_vec(&next.calculations[0]).unwrap(),old_snapshot);assert_eq!(next.input_revision,old.input_revision);
}
#[tokio::test]async fn pending_old_ruleset_job_holds_without_recalculating_or_changing_returns(){
 let store=Store::memory();let t=Tax::new(store.clone());let a=who();let r=calculated(&t,None).await;let j=t.batch_create(&a,Create{request_key:"synthetic-old-job".into(),operation:Operation::Calculate,company_ref:Some("A".into()),selections:vec![Selection{return_id:r.id.clone(),expected_revision:r.revision}]}).await.unwrap_or_else(|e|panic!("job: {}",e.1));let mut state:TaxState=store.get_json("tax:state:v1").await.unwrap().unwrap();state.batches.iter_mut().find(|v|v.id==j.id).unwrap().ruleset="nxt-ca-2025.1".into();store.set_json("tax:state:v1",&state).await.unwrap();
 let done=t.batch_step(&a,&j.id,Step{expected_revision:j.revision,request_key:"synthetic-old-step".into(),company_ref:Some("A".into())}).await.unwrap_or_else(|e|panic!("step: {}",e.1));assert_eq!(done.items[0].state,ItemState::Held);assert_eq!(done.items[0].outcome.as_ref().unwrap()["code"],"ruleset_changed");assert_eq!(done.original_manifest,j.original_manifest);assert_eq!(serde_json::to_vec(&t.get(&r.id).await.unwrap_or_else(|e|panic!("reload: {}",e.1))).unwrap(),serde_json::to_vec(&r).unwrap());
}
#[tokio::test]async fn old_filing_desk_confirmation_is_readable_but_not_currently_valid(){
 let store=Store::memory();let t=Tax::new(store.clone());let a=who();let mut r=calculated(&t,None).await;make_historical(&mut r,Some("nxt-ca-2025.1"));r.status="approved".into();r.review=Some(Review{at:"synthetic".into(),reviewer:"Reviewer [synthetic-reviewer]".into(),note:"Historical checkpoint".into(),input_hash:r.calculation.as_ref().unwrap().input_hash.clone(),output_hash:r.calculation.as_ref().unwrap().output_hash.clone()});seed(&store,&r).await;
 let fp=filing_desk::fingerprint(&r).unwrap_or_else(|e|panic!("fingerprint: {}",e.1));let mut state:TaxState=store.get_json("tax:state:v1").await.unwrap().unwrap();state.desk.filers.push(FilerGrant{user_id:a.user_id.clone(),granted_by:"Synthetic".into(),at:"synthetic".into()});state.desk.confirmations.push(DeskConfirmation{id:"synthetic-old-confirmation".into(),return_id:r.id.clone(),revision:r.revision,fingerprint:fp,by:a.label(),filer_id:a.user_id.clone(),at:"synthetic".into(),status:"recorded".into(),result:"refused".into()});store.set_json("tax:state:v1",&state).await.unwrap();let before=store.get("tax:state:v1").await.unwrap();let detail=t.desk_detail(&a,&r.id).await.unwrap_or_else(|e|panic!("desk detail: {}",e.1));assert!(detail["confirmation"].is_null());assert_eq!(detail["can_file"],false);assert_eq!(detail["sections"]["summary"]["money"]["kind"],"pending");assert!(detail["blockers"].as_array().unwrap().iter().any(|v|v["code"]=="stale_calculation"));assert_eq!(store.get("tax:state:v1").await.unwrap(),before);
}

#[tokio::test]async fn changed_added_removed_t2202_requires_a_separate_explicit_confirmation(){
 let t=Tax::new(Store::memory());let mut d=input("Synthetic tuition");d.inputs["credits_verified"]=json!(true);d.slip_groups=Some(serde_json::from_value(json!([{"kind":"T2202","issuer":"Synthetic school","boxes":{"23":100000}}])).unwrap());let r=t.save(None,d).await.unwrap_or_else(|e|panic!("tuition add: {}",e.1));assert_eq!(r.inputs["tuition_cents"],100000);assert_eq!(r.inputs["credits_verified"],false);
 let mut confirm=ReturnInput::from(&r);confirm.expected_revision=Some(r.revision);confirm.inputs["credits_verified"]=json!(true);let r=t.save(Some(&r.id),confirm).await.unwrap_or_else(|e|panic!("separate confirm: {}",e.1));assert_eq!(r.inputs["credits_verified"],true);let calc=t.calculate(&r.id,RevisionInput{expected_revision:r.revision,idempotency_key:None}).await.unwrap_or_else(|e|panic!("tuition calculate: {}",e.1));assert_eq!(calc.calculation.as_ref().unwrap().result["supported"],true);
 let mut edit=ReturnInput::from(&calc);edit.expected_revision=Some(calc.revision);edit.slip_groups.as_mut().unwrap()[0].boxes.insert("23".into(),200000);edit.inputs["credits_verified"]=json!(true);let edited=t.save(Some(&r.id),edit).await.unwrap_or_else(|e|panic!("tuition edit: {}",e.1));assert_eq!(edited.inputs["credits_verified"],false);assert_eq!(edited.inputs["tuition_cents"],200000);assert!(edited.calculation.is_none());assert_eq!(edited.calculations.len(),1);
 let mut confirm=ReturnInput::from(&edited);confirm.expected_revision=Some(edited.revision);confirm.inputs["credits_verified"]=json!(true);let confirmed=t.save(Some(&r.id),confirm).await.unwrap_or_else(|e|panic!("confirm edited: {}",e.1));assert_eq!(confirmed.inputs["credits_verified"],true);
 let mut remove=ReturnInput::from(&confirmed);remove.expected_revision=Some(confirmed.revision);remove.slip_groups=Some(vec![]);remove.inputs["credits_verified"]=json!(true);let removed=t.save(Some(&r.id),remove).await.unwrap_or_else(|e|panic!("tuition remove: {}",e.1));assert_eq!(removed.inputs["tuition_cents"],0);assert_eq!(removed.inputs["credits_verified"],false);assert!(removed.slip_groups.is_empty());assert_eq!(removed.calculations.len(),1);
}
#[test]fn unchanged_t2202_does_not_reset_credit_confirmation_for_an_unrelated_group_edit(){
 let old:Vec<nxt_os::tax::slips::Slip>=serde_json::from_value(json!([{"kind":"T4","boxes":{"14":100000}},{"kind":"T2202","boxes":{"23":100000}}])).unwrap();let mut next=old.clone();next[0].boxes.insert("14".into(),200000);let mut inputs=json!({"credits_verified":true,"payroll_verified":true});nxt_os::tax::slips::replace_inputs(&mut inputs,&old,&next).unwrap();assert_eq!(inputs["credits_verified"],true);assert_eq!(inputs["payroll_verified"],false);
}
